  DROP TEMPORARY TABLE IF EXISTS carelio_stage_countries;
  DROP TEMPORARY TABLE IF EXISTS carelio_stage_admins;
  DROP TEMPORARY TABLE IF EXISTS carelio_stage_localities;
  CREATE TEMPORARY TABLE carelio_stage_countries (
    iso2 CHAR(2) PRIMARY KEY, iso3 CHAR(3) UNIQUE, iso_numeric CHAR(3) UNIQUE,
    name VARCHAR(200), source_standard VARCHAR(100), source_ref VARCHAR(160) UNIQUE,
    source_url VARCHAR(1024), status VARCHAR(20), active TINYINT, notes TEXT
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
  CREATE TEMPORARY TABLE carelio_stage_admins (
    iso2 CHAR(2), parent_ref VARCHAR(160), admin_level TINYINT,
    admin_code VARCHAR(100), name VARCHAR(200), admin_type VARCHAR(60),
    source_standard VARCHAR(100), source_ref VARCHAR(160), source_url VARCHAR(1024),
    status VARCHAR(20), active TINYINT, notes TEXT, PRIMARY KEY(iso2,source_ref)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
  CREATE TEMPORARY TABLE carelio_stage_localities (
    iso2 CHAR(2), admin_ref VARCHAR(160), name VARCHAR(200), locality_type VARCHAR(60),
    source_standard VARCHAR(100), source_ref VARCHAR(160), source_url VARCHAR(1024),
    status VARCHAR(20), active TINYINT, notes TEXT, PRIMARY KEY(iso2,source_ref),
    UNIQUE KEY uq_stage_locality_name (iso2,admin_ref,name)
  ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
  -- 02 Countries (ISO identifiers from pinned GeoNames countryInfo)

  -- 03 Saint Lucia: source records, with explicit parent references

  -- 04 Antigua and Barbuda: source records, with explicit parent references

  -- 05 Dominica: source records, with explicit parent references

  -- 06 Grenada: source records, with explicit parent references

  -- 07 Saint Kitts and Nevis: source records, with explicit parent references

  -- 08 Saint Vincent and the Grenadines: source records, with explicit parent references

  -- 09 Anguilla: source records, with explicit parent references

  -- 10 British Virgin Islands: source records, with explicit parent references

  -- 11 Montserrat: source records, with explicit parent references

  -- 12 Guadeloupe: source records, with explicit parent references

  -- 13 Martinique: source records, with explicit parent references

  -- 14 Saint Martin: source records, with explicit parent references

  -- 15 Barbados: source records, with explicit parent references

  -- 16 Trinidad and Tobago: source records, with explicit parent references

  -- 17 Jamaica: source records, with explicit parent references

  -- 18 Guyana: source records, with explicit parent references

  -- 19 Belize: source records, with explicit parent references

  -- 20 Bahamas: source records, with explicit parent references

  -- 21 Cayman Islands: source records, with explicit parent references

  -- 22 Cuba: source records, with explicit parent references

  -- 23 CuraÃ§ao: source records, with explicit parent references

  -- 24 Dominican Republic: source records, with explicit parent references

  -- 25 Haiti: source records, with explicit parent references

  -- 26 Puerto Rico: source records, with explicit parent references

  -- 27 Sint Maarten: source records, with explicit parent references

  -- 28 Suriname: source records, with explicit parent references

  -- 29 Turks and Caicos Islands: source records, with explicit parent references

  -- 30 United States Virgin Islands: source records, with explicit parent references

  -- 31 Validate staging and existing records before writes
  IF EXISTS (SELECT iso2,IFNULL(parent_ref,''),admin_level,LCASE(TRIM(name)) FROM carelio_stage_admins GROUP BY iso2,IFNULL(parent_ref,''),admin_level,LCASE(TRIM(name)) HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Duplicate administrative name in input'; END IF;
  IF EXISTS (SELECT iso2,admin_ref,LCASE(TRIM(name)) FROM carelio_stage_localities GROUP BY iso2,admin_ref,LCASE(TRIM(name)) HAVING COUNT(*)>1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Duplicate locality name in input'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_localities l LEFT JOIN carelio_stage_admins a ON a.iso2=l.iso2 AND a.source_ref=l.admin_ref WHERE a.source_ref IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unresolved locality parent in input'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_admins a LEFT JOIN carelio_stage_admins p ON p.iso2=a.iso2 AND p.source_ref=a.parent_ref WHERE a.parent_ref IS NOT NULL AND (p.source_ref IS NULL OR p.admin_level<>a.admin_level-1)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Unresolved administrative parent in input'; END IF;
  START TRANSACTION;
  SET transaction_started=TRUE;
  IF EXISTS (SELECT iso2 FROM carelio_geo_countries GROUP BY iso2 HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate country iso2'; END IF;
  IF EXISTS (SELECT iso3 FROM carelio_geo_countries GROUP BY iso3 HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate country iso3'; END IF;
  IF EXISTS (SELECT iso_numeric FROM carelio_geo_countries GROUP BY iso_numeric HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate country numeric'; END IF;
  IF EXISTS (SELECT source_ref FROM carelio_geo_countries GROUP BY source_ref HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate country source refs'; END IF;
  IF EXISTS (SELECT country_id,source_ref FROM carelio_geo_admin_areas GROUP BY country_id,source_ref HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate administrative source refs'; END IF;
  IF EXISTS (SELECT country_id,source_ref FROM carelio_geo_localities GROUP BY country_id,source_ref HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate locality source refs'; END IF;
  IF EXISTS (SELECT country_id,parent_key,admin_level,name_key FROM carelio_geo_admin_areas GROUP BY country_id,parent_key,admin_level,name_key HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate administrative names'; END IF;
  IF EXISTS (SELECT country_id,admin_area_id,name_key FROM carelio_geo_localities GROUP BY country_id,admin_area_id,name_key HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Duplicate locality names'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_countries c ON c.id=a.country_id WHERE c.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Orphan administrative areas'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.parent_admin_area_id IS NOT NULL AND p.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Orphan administrative parents'; END IF;
  IF EXISTS (SELECT l.id FROM carelio_geo_localities l LEFT JOIN carelio_geo_countries c ON c.id=l.country_id LEFT JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE c.id IS NULL OR a.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Orphan localities'; END IF;
  IF EXISTS (SELECT l.id FROM carelio_geo_localities l JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE l.country_id<>a.country_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Country/admin mismatches'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.country_id<>p.country_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Administrative parent country mismatches'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.admin_level>4 OR (a.admin_level<=1 AND a.parent_admin_area_id IS NOT NULL) OR (a.admin_level>1 AND (p.id IS NULL OR p.admin_level<>a.admin_level-1))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Invalid administrative levels or cycles'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_localities WHERE country_id IS NULL OR admin_area_id IS NULL UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE country_id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: NULL required parent relationships'; END IF;
  IF EXISTS (SELECT l.id FROM carelio_geo_localities l JOIN carelio_geo_countries c ON c.id=l.country_id JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE l.active=1 AND (c.active=0 OR a.active=0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Invalid active locality references'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a JOIN carelio_geo_countries c ON c.id=a.country_id LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.active=1 AND (c.active=0 OR p.active=0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Invalid active administrative references'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE source_ref IS NULL OR TRIM(source_ref)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_ref IS NULL OR TRIM(source_ref)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_ref IS NULL OR TRIM(source_ref)='') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Missing source references'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE source_url IS NULL OR TRIM(source_url)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_url IS NULL OR TRIM(source_url)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_url IS NULL OR TRIM(source_url)='') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Missing source URLs'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE source_standard IS NULL OR TRIM(source_standard)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_standard IS NULL OR TRIM(source_standard)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_standard IS NULL OR TRIM(source_standard)='') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Missing source standards'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0) UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0) UNION ALL SELECT id FROM carelio_geo_localities WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Pre-existing QA failure: Invalid status or active values'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_countries s JOIN carelio_geo_countries c ON c.iso2=s.iso2 OR c.iso3=s.iso3 OR c.iso_numeric=s.iso_numeric OR c.source_ref=s.source_ref WHERE c.iso2<>s.iso2 OR c.iso3<>s.iso3 OR c.iso_numeric<>s.iso_numeric OR c.name<>s.name OR c.source_ref<>s.source_ref) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Country identity conflict; existing rows preserved'; END IF;
    SELECT s.iso2,s.iso3,s.iso_numeric,s.name,s.source_standard,s.source_ref,s.source_url,s.status,s.active,s.notes FROM carelio_stage_countries s
    WHERE NOT EXISTS (SELECT 1 FROM carelio_geo_countries c WHERE c.iso2=s.iso2);
  WHILE current_level<=4 DO
  IF EXISTS (SELECT 1 FROM carelio_stage_admins s JOIN carelio_geo_countries c ON c.iso2=s.iso2 LEFT JOIN carelio_geo_admin_areas p ON p.country_id=c.id AND p.source_ref=s.parent_ref WHERE s.admin_level=current_level AND s.parent_ref IS NOT NULL AND p.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Administrative parent missing during import'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_admins s JOIN carelio_geo_countries c ON c.iso2=s.iso2 LEFT JOIN carelio_geo_admin_areas p ON p.country_id=c.id AND p.source_ref=s.parent_ref JOIN carelio_geo_admin_areas a ON a.country_id=c.id AND (a.source_ref=s.source_ref OR (a.parent_key=IFNULL(p.id,0) AND a.admin_level=s.admin_level AND a.name_key=LCASE(TRIM(s.name)))) WHERE s.admin_level=current_level AND (a.source_ref<>s.source_ref OR a.name<>s.name OR a.admin_type<>s.admin_type OR a.admin_level<>s.admin_level OR NOT(a.admin_code<=>s.admin_code) OR NOT(a.parent_admin_area_id<=>p.id))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Administrative identity conflict; existing rows preserved'; END IF;
    SELECT c.id,p.id,s.admin_level,s.admin_code,s.name,s.admin_type,s.source_standard,s.source_ref,s.source_url,s.status,s.active,s.notes
    FROM carelio_stage_admins s JOIN carelio_geo_countries c ON c.iso2=s.iso2
    LEFT JOIN carelio_geo_admin_areas p ON p.country_id=c.id AND p.source_ref=s.parent_ref
    WHERE s.admin_level=current_level AND NOT EXISTS
      (SELECT 1 FROM carelio_geo_admin_areas a WHERE a.country_id=c.id AND a.source_ref=s.source_ref);
    SET current_level=current_level+1;
  END WHILE;
  IF EXISTS (SELECT 1 FROM carelio_stage_localities s JOIN carelio_geo_countries c ON c.iso2=s.iso2 JOIN carelio_geo_admin_areas a ON a.country_id=c.id AND a.source_ref=s.admin_ref JOIN carelio_geo_localities l ON l.country_id=c.id AND l.source_ref=s.source_ref WHERE l.source_ref<>s.source_ref OR l.name<>s.name OR l.locality_type<>s.locality_type OR l.admin_area_id<>a.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Locality identity/source conflict; transaction rolled back; existing IDs preserved'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_localities s JOIN carelio_geo_countries c ON c.iso2=s.iso2 JOIN carelio_geo_admin_areas a ON a.country_id=c.id AND a.source_ref=s.admin_ref JOIN carelio_geo_localities l ON l.country_id=c.id AND l.admin_area_id=a.id AND l.name_key=LCASE(TRIM(s.name)) WHERE l.source_ref<>s.source_ref OR l.name<>s.name OR l.locality_type<>s.locality_type OR l.admin_area_id<>a.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Locality identity/source conflict; transaction rolled back; existing IDs preserved'; END IF;
  SELECT c.id,a.id,s.name,s.locality_type,s.source_standard,s.source_ref,s.source_url,s.status,s.active,s.notes
  FROM carelio_stage_localities s JOIN carelio_geo_countries c ON c.iso2=s.iso2
  JOIN carelio_geo_admin_areas a ON a.country_id=c.id AND a.source_ref=s.admin_ref
  WHERE NOT EXISTS (SELECT 1 FROM carelio_geo_localities l WHERE l.country_id=c.id AND l.source_ref=s.source_ref);
  -- 32 Critical postconditions (any failure rolls back ALL geographic writes)
  IF EXISTS (SELECT iso2 FROM carelio_geo_countries GROUP BY iso2 HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate country iso2'; END IF;
  IF EXISTS (SELECT iso3 FROM carelio_geo_countries GROUP BY iso3 HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate country iso3'; END IF;
  IF EXISTS (SELECT iso_numeric FROM carelio_geo_countries GROUP BY iso_numeric HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate country numeric'; END IF;
  IF EXISTS (SELECT source_ref FROM carelio_geo_countries GROUP BY source_ref HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate country source refs'; END IF;
  IF EXISTS (SELECT country_id,source_ref FROM carelio_geo_admin_areas GROUP BY country_id,source_ref HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate administrative source refs'; END IF;
  IF EXISTS (SELECT country_id,source_ref FROM carelio_geo_localities GROUP BY country_id,source_ref HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate locality source refs'; END IF;
  IF EXISTS (SELECT country_id,parent_key,admin_level,name_key FROM carelio_geo_admin_areas GROUP BY country_id,parent_key,admin_level,name_key HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate administrative names'; END IF;
  IF EXISTS (SELECT country_id,admin_area_id,name_key FROM carelio_geo_localities GROUP BY country_id,admin_area_id,name_key HAVING COUNT(*) > 1) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Duplicate locality names'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_countries c ON c.id=a.country_id WHERE c.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Orphan administrative areas'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.parent_admin_area_id IS NOT NULL AND p.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Orphan administrative parents'; END IF;
  IF EXISTS (SELECT l.id FROM carelio_geo_localities l LEFT JOIN carelio_geo_countries c ON c.id=l.country_id LEFT JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE c.id IS NULL OR a.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Orphan localities'; END IF;
  IF EXISTS (SELECT l.id FROM carelio_geo_localities l JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE l.country_id<>a.country_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Country/admin mismatches'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.country_id<>p.country_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Administrative parent country mismatches'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.admin_level>4 OR (a.admin_level<=1 AND a.parent_admin_area_id IS NOT NULL) OR (a.admin_level>1 AND (p.id IS NULL OR p.admin_level<>a.admin_level-1))) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Invalid administrative levels or cycles'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_localities WHERE country_id IS NULL OR admin_area_id IS NULL UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE country_id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: NULL required parent relationships'; END IF;
  IF EXISTS (SELECT l.id FROM carelio_geo_localities l JOIN carelio_geo_countries c ON c.id=l.country_id JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE l.active=1 AND (c.active=0 OR a.active=0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Invalid active locality references'; END IF;
  IF EXISTS (SELECT a.id FROM carelio_geo_admin_areas a JOIN carelio_geo_countries c ON c.id=a.country_id LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.active=1 AND (c.active=0 OR p.active=0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Invalid active administrative references'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE source_ref IS NULL OR TRIM(source_ref)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_ref IS NULL OR TRIM(source_ref)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_ref IS NULL OR TRIM(source_ref)='') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Missing source references'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE source_url IS NULL OR TRIM(source_url)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_url IS NULL OR TRIM(source_url)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_url IS NULL OR TRIM(source_url)='') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Missing source URLs'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE source_standard IS NULL OR TRIM(source_standard)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_standard IS NULL OR TRIM(source_standard)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_standard IS NULL OR TRIM(source_standard)='') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Missing source standards'; END IF;
  IF EXISTS (SELECT id FROM carelio_geo_countries WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0) UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0) UNION ALL SELECT id FROM carelio_geo_localities WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Post-import QA failure: Invalid status or active values'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_countries s LEFT JOIN carelio_geo_countries t ON t.iso2=s.iso2 WHERE t.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing records after import: countries'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_admins s JOIN carelio_geo_countries c ON c.iso2=s.iso2 LEFT JOIN carelio_geo_admin_areas t ON t.country_id=c.id AND t.source_ref=s.source_ref WHERE t.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing records after import: admin_areas'; END IF;
  IF EXISTS (SELECT 1 FROM carelio_stage_localities s JOIN carelio_geo_countries c ON c.iso2=s.iso2 LEFT JOIN carelio_geo_localities t ON t.country_id=c.id AND t.source_ref=s.source_ref WHERE t.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Missing records after import: localities'; END IF;
  -- 33 Dataset version (immutable checksum, repeat runs preserve imported_at)
  IF EXISTS (SELECT 1 FROM carelio_geo_dataset_versions WHERE dataset_name='CarelioEMR Caribbean Geographic Demographics' AND dataset_version='1.0.0' AND checksum<>'7c039e6bc88b2634bb1706b1a5092a29e023afa9559de4b13b15cc02667035ee') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Dataset version already registered with another checksum'; END IF;
  SELECT 'CarelioEMR Caribbean Geographic Demographics','1.0.0',
    'Saint Lucia CSO 2010; TCI Statistics 2012; BVI Tourist Board; GeoNames CC BY 4.0; TT RDLG terminology',
    'https://www.geonames.org/export/','2026-09-18',
    (SELECT COUNT(*) FROM carelio_stage_countries)+(SELECT COUNT(*) FROM carelio_stage_admins)+(SELECT COUNT(*) FROM carelio_stage_localities),
    '7c039e6bc88b2634bb1706b1a5092a29e023afa9559de4b13b15cc02667035ee','REVIEW_REQUIRED',
    (SELECT COUNT(*) FROM carelio_stage_countries),(SELECT COUNT(*) FROM carelio_stage_admins),(SELECT COUNT(*) FROM carelio_stage_localities)
  WHERE NOT EXISTS (SELECT 1 FROM carelio_geo_dataset_versions WHERE dataset_name='CarelioEMR Caribbean Geographic Demographics' AND dataset_version='1.0.0');
  COMMIT;
  SET transaction_started=FALSE;
  DROP TEMPORARY TABLE carelio_stage_countries;
  DROP TEMPORARY TABLE carelio_stage_admins;
  DROP TEMPORARY TABLE carelio_stage_localities;
  DO RELEASE_LOCK(lock_name);
  SET SESSION sql_mode = @carelio_previous_sql_mode;
END$$
DELIMITER ;
-- 34 Verification report (all issue counts must be zero)
-- CarelioEMR Caribbean Geographic Demographics 1.0.0: read-only QA
-- Counts cover ALL carelio_geo_* rows. Every issue_count must be zero.
-- REVIEW_REQUIRED is a provenance state, not a structural integrity failure.
SET NAMES utf8mb4 COLLATE utf8mb4_bin;
SELECT 'Countries installed' AS metric, COUNT(*) AS record_count FROM carelio_geo_countries
UNION ALL SELECT 'Administrative areas installed', COUNT(*) FROM carelio_geo_admin_areas
UNION ALL SELECT 'Localities installed', COUNT(*) FROM carelio_geo_localities;
SELECT 'Duplicate country iso2' AS metric, COUNT(*) AS issue_count FROM (SELECT iso2 FROM carelio_geo_countries GROUP BY iso2 HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate country iso3' AS metric, COUNT(*) AS issue_count FROM (SELECT iso3 FROM carelio_geo_countries GROUP BY iso3 HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate country numeric' AS metric, COUNT(*) AS issue_count FROM (SELECT iso_numeric FROM carelio_geo_countries GROUP BY iso_numeric HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate country source refs' AS metric, COUNT(*) AS issue_count FROM (SELECT source_ref FROM carelio_geo_countries GROUP BY source_ref HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate administrative source refs' AS metric, COUNT(*) AS issue_count FROM (SELECT country_id,source_ref FROM carelio_geo_admin_areas GROUP BY country_id,source_ref HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate locality source refs' AS metric, COUNT(*) AS issue_count FROM (SELECT country_id,source_ref FROM carelio_geo_localities GROUP BY country_id,source_ref HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate administrative names' AS metric, COUNT(*) AS issue_count FROM (SELECT country_id,parent_key,admin_level,name_key FROM carelio_geo_admin_areas GROUP BY country_id,parent_key,admin_level,name_key HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Duplicate locality names' AS metric, COUNT(*) AS issue_count FROM (SELECT country_id,admin_area_id,name_key FROM carelio_geo_localities GROUP BY country_id,admin_area_id,name_key HAVING COUNT(*) > 1) q
UNION ALL
SELECT 'Orphan administrative areas' AS metric, COUNT(*) AS issue_count FROM (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_countries c ON c.id=a.country_id WHERE c.id IS NULL) q
UNION ALL
SELECT 'Orphan administrative parents' AS metric, COUNT(*) AS issue_count FROM (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.parent_admin_area_id IS NOT NULL AND p.id IS NULL) q
UNION ALL
SELECT 'Orphan localities' AS metric, COUNT(*) AS issue_count FROM (SELECT l.id FROM carelio_geo_localities l LEFT JOIN carelio_geo_countries c ON c.id=l.country_id LEFT JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE c.id IS NULL OR a.id IS NULL) q
UNION ALL
SELECT 'Country/admin mismatches' AS metric, COUNT(*) AS issue_count FROM (SELECT l.id FROM carelio_geo_localities l JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE l.country_id<>a.country_id) q
UNION ALL
SELECT 'Administrative parent country mismatches' AS metric, COUNT(*) AS issue_count FROM (SELECT a.id FROM carelio_geo_admin_areas a JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.country_id<>p.country_id) q
UNION ALL
SELECT 'Invalid administrative levels or cycles' AS metric, COUNT(*) AS issue_count FROM (SELECT a.id FROM carelio_geo_admin_areas a LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.admin_level>4 OR (a.admin_level<=1 AND a.parent_admin_area_id IS NOT NULL) OR (a.admin_level>1 AND (p.id IS NULL OR p.admin_level<>a.admin_level-1))) q
UNION ALL
SELECT 'NULL required parent relationships' AS metric, COUNT(*) AS issue_count FROM (SELECT id FROM carelio_geo_localities WHERE country_id IS NULL OR admin_area_id IS NULL UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE country_id IS NULL) q
UNION ALL
SELECT 'Invalid active locality references' AS metric, COUNT(*) AS issue_count FROM (SELECT l.id FROM carelio_geo_localities l JOIN carelio_geo_countries c ON c.id=l.country_id JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id WHERE l.active=1 AND (c.active=0 OR a.active=0)) q
UNION ALL
SELECT 'Invalid active administrative references' AS metric, COUNT(*) AS issue_count FROM (SELECT a.id FROM carelio_geo_admin_areas a JOIN carelio_geo_countries c ON c.id=a.country_id LEFT JOIN carelio_geo_admin_areas p ON p.id=a.parent_admin_area_id WHERE a.active=1 AND (c.active=0 OR p.active=0)) q
UNION ALL
SELECT 'Missing source references' AS metric, COUNT(*) AS issue_count FROM (SELECT id FROM carelio_geo_countries WHERE source_ref IS NULL OR TRIM(source_ref)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_ref IS NULL OR TRIM(source_ref)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_ref IS NULL OR TRIM(source_ref)='') q
UNION ALL
SELECT 'Missing source URLs' AS metric, COUNT(*) AS issue_count FROM (SELECT id FROM carelio_geo_countries WHERE source_url IS NULL OR TRIM(source_url)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_url IS NULL OR TRIM(source_url)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_url IS NULL OR TRIM(source_url)='') q
UNION ALL
SELECT 'Missing source standards' AS metric, COUNT(*) AS issue_count FROM (SELECT id FROM carelio_geo_countries WHERE source_standard IS NULL OR TRIM(source_standard)='' UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE source_standard IS NULL OR TRIM(source_standard)='' UNION ALL SELECT id FROM carelio_geo_localities WHERE source_standard IS NULL OR TRIM(source_standard)='') q
UNION ALL
SELECT 'Invalid status or active values' AS metric, COUNT(*) AS issue_count FROM (SELECT id FROM carelio_geo_countries WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0) UNION ALL SELECT id FROM carelio_geo_admin_areas WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0) UNION ALL SELECT id FROM carelio_geo_localities WHERE status NOT IN ('VERIFIED','REVIEW_REQUIRED','DEPRECATED') OR status IS NULL OR active NOT IN (0,1) OR active IS NULL OR (status='DEPRECATED' AND active<>0)) q;

SELECT c.iso2,c.name,
 (SELECT COUNT(*) FROM carelio_geo_admin_areas a WHERE a.country_id=c.id) AS administrative_areas,
 (SELECT COUNT(*) FROM carelio_geo_localities l WHERE l.country_id=c.id) AS localities,
 (SELECT COUNT(*) FROM carelio_geo_localities l WHERE l.country_id=c.id AND l.status='VERIFIED') AS verified_localities,
 (SELECT COUNT(*) FROM carelio_geo_localities l WHERE l.country_id=c.id AND l.status='REVIEW_REQUIRED') AS review_required_localities,
 (SELECT COUNT(*) FROM carelio_geo_localities l WHERE l.country_id=c.id AND l.active=1) AS active_localities
FROM carelio_geo_countries c ORDER BY c.iso2;
SELECT a.name AS saint_lucia_district, COUNT(l.id) AS localities,
 SUM(l.status='VERIFIED') AS verified_localities
FROM carelio_geo_countries c JOIN carelio_geo_admin_areas a ON a.country_id=c.id
LEFT JOIN carelio_geo_localities l ON l.country_id=c.id AND l.admin_area_id=a.id
WHERE c.iso2='LC' GROUP BY a.id,a.name ORDER BY a.name;
SELECT dataset_name,dataset_version,release_date,imported_at,record_count,
 country_count,admin_area_count,locality_count,checksum,status
FROM carelio_geo_dataset_versions ORDER BY id;
-- Detail diagnostics for source conflicts and broken hierarchy:
SELECT country_id,source_ref,COUNT(*) AS copies FROM carelio_geo_localities
GROUP BY country_id,source_ref HAVING COUNT(*)>1;
SELECT l.id,l.name,l.country_id,l.admin_area_id,a.country_id AS parent_country_id
FROM carelio_geo_localities l LEFT JOIN carelio_geo_admin_areas a ON a.id=l.admin_area_id
WHERE a.id IS NULL OR a.country_id<>l.country_id;

-- Release coverage: compares calculated live counts with this pinned manifest.
SELECT 'Countries below release coverage' AS metric, COUNT(*) AS issue_count FROM JSON_TABLE('[{"iso2":"LC","admins":10,"localities":367},{"iso2":"AG","admins":8,"localities":154},{"iso2":"DM","admins":10,"localities":124},{"iso2":"GD","admins":7,"localities":280},{"iso2":"KN","admins":14,"localities":124},{"iso2":"VC","admins":6,"localities":140},{"iso2":"AI","admins":14,"localities":15},{"iso2":"VG","admins":4,"localities":5},{"iso2":"MS","admins":3,"localities":31},{"iso2":"GP","admins":36,"localities":404},{"iso2":"MQ","admins":40,"localities":611},{"iso2":"MF","admins":1,"localities":33},{"iso2":"BB","admins":11,"localities":563},{"iso2":"TT","admins":15,"localities":439},{"iso2":"JM","admins":14,"localities":3351},{"iso2":"GY","admins":10,"localities":813},{"iso2":"BZ","admins":6,"localities":504},{"iso2":"BS","admins":32,"localities":315},{"iso2":"KY","admins":6,"localities":15},{"iso2":"CU","admins":16,"localities":7927},{"iso2":"CW","admins":1,"localities":78},{"iso2":"DO","admins":32,"localities":6730},{"iso2":"HT","admins":10,"localities":8746},{"iso2":"PR","admins":78,"localities":2450},{"iso2":"SX","admins":1,"localities":14},{"iso2":"SR","admins":10,"localities":511},{"iso2":"TC","admins":7,"localities":25},{"iso2":"VI","admins":3,"localities":211}]', '$[*]' COLUMNS (iso2 CHAR(2) PATH '$.iso2', admins INT PATH '$.admins', localities INT PATH '$.localities')) e LEFT JOIN carelio_geo_countries c ON c.iso2=e.iso2 WHERE c.id IS NULL OR (SELECT COUNT(*) FROM carelio_geo_admin_areas a WHERE a.country_id=c.id)<e.admins OR (SELECT COUNT(*) FROM carelio_geo_localities l WHERE l.country_id=c.id)<e.localities;
SELECT 'Missing release registration or checksum mismatch' AS metric, IF(COUNT(*)=1,0,1) AS issue_count FROM carelio_geo_dataset_versions WHERE dataset_name='CarelioEMR Caribbean Geographic Demographics' AND dataset_version='1.0.0' AND checksum='7c039e6bc88b2634bb1706b1a5092a29e023afa9559de4b13b15cc02667035ee';
